package adapters

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type ClaudeScanner struct {
	Root string
}

func (s ClaudeScanner) Name() string {
	return "claude"
}

func (s ClaudeScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if !core.ExistingDir(s.Root) {
		result.Skipped = true
		result.Message = "Claude projects directory not found"
		return result
	}
	entries, err := os.ReadDir(s.Root)
	if err != nil {
		result.Err = err
		return result
	}
	for _, entry := range entries {
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		if !entry.IsDir() {
			continue
		}
		projectDir := filepath.Join(s.Root, entry.Name())
		projectPath := core.DecodeClaudeProjectDir(entry.Name())
		_ = filepath.WalkDir(projectDir, func(path string, d fs.DirEntry, err error) error {
			if err != nil || ctx.Err() != nil {
				return nil
			}
			if d.IsDir() || filepath.Ext(path) != ".jsonl" {
				return nil
			}
			info, statErr := d.Info()
			if statErr != nil {
				return nil
			}
			nativeID := strings.TrimSuffix(filepath.Base(path), ".jsonl")
			if nativeID == "" {
				nativeID = path
			}
			meta := readJSONLMetadata(path)
			lastActivity := core.NonZeroTime(meta.LastTimestamp, info.ModTime())
			created := core.NonZeroTime(meta.FirstTimestamp, info.ModTime())
			session := core.NewSession("claude", nativeID)
			session.ProjectPath = projectPath
			session.Agent = "claude"
			session.Title = "Claude: " + core.ProjectName(projectPath)
			session.Status = core.StatusUnknown
			session.LastActivityAt = lastActivity.UTC()
			session.CreatedAt = created.UTC()
			session.ResumeCommand = "cd " + core.ShellQuote(projectPath) + " && claude -c"
			session.RawPath = path
			result.Sessions = append(result.Sessions, session)
			return nil
		})
	}
	return result
}

type jsonlMetadata struct {
	FirstTimestamp time.Time
	LastTimestamp  time.Time
}

func readJSONLMetadata(path string) jsonlMetadata {
	file, err := os.Open(path)
	if err != nil {
		return jsonlMetadata{}
	}
	defer file.Close() //nolint:errcheck
	var meta jsonlMetadata
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), 2*1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var row map[string]any
		if err := json.Unmarshal([]byte(line), &row); err != nil {
			continue
		}
		ts := parseTimestamp(row)
		if ts.IsZero() {
			continue
		}
		if meta.FirstTimestamp.IsZero() {
			meta.FirstTimestamp = ts
		}
		meta.LastTimestamp = ts
	}
	return meta
}

func parseTimestamp(row map[string]any) time.Time {
	for _, key := range []string{"timestamp", "created_at", "createdAt", "time"} {
		raw, ok := row[key].(string)
		if !ok || raw == "" {
			continue
		}
		for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02 15:04:05"} {
			t, err := time.Parse(layout, raw)
			if err == nil {
				return t.UTC()
			}
		}
	}
	return time.Time{}
}

func readTextCandidatesFromJSONL(path string, limit int) ([]string, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close() //nolint:errcheck
	var out []string
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), 2*1024*1024)
	for scanner.Scan() {
		if limit > 0 && len(out) >= limit {
			break
		}
		var row any
		if err := json.Unmarshal(scanner.Bytes(), &row); err != nil {
			continue
		}
		for _, text := range extractText(row) {
			text = cleanCandidate(text)
			if text != "" {
				out = append(out, text)
				if limit > 0 && len(out) >= limit {
					break
				}
			}
		}
	}
	if err := scanner.Err(); err != nil && !errors.Is(err, bufio.ErrTooLong) {
		return out, err
	}
	return out, nil
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestClaudeScannerFindsJSONL(t *testing.T) {
	root := t.TempDir()
	project := filepath.Join(root, "-tmp-project")
	if err := os.MkdirAll(project, 0755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(project, "session-1.jsonl")
	data := `{"timestamp":"2026-01-01T00:00:00Z","message":{"role":"user","content":"Build auth"}}` + "\n"
	if err := os.WriteFile(path, []byte(data), 0644); err != nil {
		t.Fatal(err)
	}
	res := ClaudeScanner{Root: root}.Scan(context.Background())
	if res.Err != nil {
		t.Fatal(res.Err)
	}
	if len(res.Sessions) != 1 {
		t.Fatalf("expected one session, got %d", len(res.Sessions))
	}
	if res.Sessions[0].Agent != "claude" {
		t.Fatalf("expected claude agent, got %q", res.Sessions[0].Agent)
	}
}

package adapters

import (
	"context"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type CopilotScanner struct {
	Root string
}

func (s CopilotScanner) Name() string {
	return "copilot"
}

func (s CopilotScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if !core.ExistingDir(s.Root) {
		result.Skipped = true
		result.Message = "Copilot session-state directory not found"
		return result
	}
	entries, err := os.ReadDir(s.Root)
	if err != nil {
		result.Err = err
		return result
	}
	for _, entry := range entries {
		if ctx.Err() != nil {
			result.Err = ctx.Err()
			return result
		}
		path := filepath.Join(s.Root, entry.Name())
		if strings.HasPrefix(entry.Name(), ".") {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if !entry.IsDir() && !isCopilotSessionFile(entry.Name()) {
			continue
		}
		last := info.ModTime()
		if entry.IsDir() {
			last = newestModTime(path, last)
		}
		nativeID := strings.TrimSuffix(entry.Name(), filepath.Ext(entry.Name()))
		session := core.NewSession("copilot", nativeID)
		session.Agent = "copilot"
		session.Title = "Copilot: " + core.Truncate(nativeID, 32)
		session.Status = core.StatusUnknown
		session.LastActivityAt = last.UTC()
		session.CreatedAt = last.UTC()
		session.ResumeCommand = "copilot --resume=" + core.ShellQuote(nativeID)
		session.RawPath = path
		result.Sessions = append(result.Sessions, session)
	}
	sort.Slice(result.Sessions, func(i, j int) bool {
		return result.Sessions[i].LastActivityAt.After(result.Sessions[j].LastActivityAt)
	})
	return result
}

func isCopilotSessionFile(name string) bool {
	switch filepath.Ext(name) {
	case ".json", ".jsonl", ".db", ".md", ".yaml":
		return true
	default:
		return false
	}
}

func newestModTime(root string, fallback time.Time) time.Time {
	newest := fallback
	_ = filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		info, err := d.Info()
		if err == nil && info.ModTime().After(newest) {
			newest = info.ModTime()
		}
		return nil
	})
	return newest
}

package adapters

import (
	"context"
	"encoding/json"
	"os/exec"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type HerdrScanner struct{}

func (s HerdrScanner) Name() string {
	return "herdr"
}

func (s HerdrScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if _, err := exec.LookPath("herdr"); err != nil {
		result.Skipped = true
		result.Message = "herdr not found"
		return result
	}
	out, err := exec.CommandContext(ctx, "herdr", "agent", "list", "--json").Output()
	if err != nil {
		result.Skipped = true
		result.Message = "herdr agent list unavailable; is the server running?"
		return result
	}
	var payload any
	if err := json.Unmarshal(out, &payload); err != nil {
		result.Err = err
		return result
	}
	now := time.Now().UTC()
	for _, item := range objectList(payload) {
		nativeID := firstString(item, "id", "agent_id", "pane_id", "terminal_id", "name")
		if nativeID == "" {
			continue
		}
		cwd := firstString(item, "cwd", "project_path", "foreground_cwd")
		agent := firstString(item, "agent", "label", "name", "display_agent")
		status := normalizeStatus(firstString(item, "status", "state", "agent_state"))
		if status == "" {
			status = core.StatusUnknown
		}
		title := firstString(item, "title", "name", "label")
		if title == "" {
			title = "Herdr: " + core.Truncate(nativeID, 32)
		}
		session := core.NewSession("herdr", nativeID)
		session.ProjectPath = cwd
		session.Agent = firstNonEmpty(agent, "agent")
		session.Title = title
		session.Status = status
		session.LastActivityAt = now
		session.CreatedAt = now
		session.AttachCommand = "herdr agent attach " + core.ShellQuote(nativeID)
		result.Sessions = append(result.Sessions, session)
		result.Runtimes = append(result.Runtimes, core.RuntimeInstance{
			ID:            core.RuntimeID("herdr", nativeID),
			SessionID:     session.ID,
			Backend:       "herdr",
			NativeID:      nativeID,
			Surface:       nativeID,
			ProjectPath:   cwd,
			Command:       agent,
			Status:        status,
			AttachCommand: session.AttachCommand,
			UpdatedAt:     now,
		})
	}
	return result
}

func objectList(v any) []map[string]any {
	switch x := v.(type) {
	case []any:
		return mapsFromArray(x)
	case map[string]any:
		for _, key := range []string{"agents", "items", "data", "results", "panes"} {
			if arr, ok := x[key].([]any); ok {
				return mapsFromArray(arr)
			}
		}
		return []map[string]any{x}
	default:
		return nil
	}
}

func mapsFromArray(arr []any) []map[string]any {
	var out []map[string]any
	for _, item := range arr {
		if m, ok := item.(map[string]any); ok {
			out = append(out, m)
		}
	}
	return out
}

func firstString(m map[string]any, keys ...string) string {
	for _, key := range keys {
		if v, ok := m[key]; ok {
			switch t := v.(type) {
			case string:
				if strings.TrimSpace(t) != "" {
					return strings.TrimSpace(t)
				}
			case map[string]any:
				if s := firstString(t, "id", "name", "label", "path", "state", "status"); s != "" {
					return s
				}
			}
		}
	}
	return ""
}

func normalizeStatus(status string) string {
	switch strings.ToLower(strings.TrimSpace(status)) {
	case "blocked", "waiting", "needs_attention", "needs-attention":
		return core.StatusNeedsAttention
	case "working", "busy", "running":
		return core.StatusWorking
	case "idle", "ready":
		return core.StatusIdle
	case "done", "complete", "completed":
		return core.StatusDone
	case "stale":
		return core.StatusStale
	default:
		return ""
	}
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

