package adapters

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

func extractText(v any) []string {
	var out []string
	var walk func(any)
	walk = func(value any) {
		switch x := value.(type) {
		case map[string]any:
			if role, _ := x["role"].(string); role != "" && role != "user" && role != "assistant" {
				return
			}
			for _, key := range []string{"text", "content", "message", "prompt", "response"} {
				if nested, ok := x[key]; ok {
					walk(nested)
				}
			}
		case []any:
			for _, item := range x {
				walk(item)
			}
		case string:
			if strings.TrimSpace(x) != "" {
				out = append(out, x)
			}
		case fmt.Stringer:
			out = append(out, x.String())
		}
	}
	walk(v)
	return out
}

func cleanCandidate(text string) string {
	text = strings.Map(func(r rune) rune {
		if r == '\n' || r == '\t' {
			return ' '
		}
		if unicode.IsControl(r) {
			return -1
		}
		return r
	}, text)
	text = strings.Join(strings.Fields(text), " ")
	if strings.HasPrefix(text, "{") || strings.HasPrefix(text, "[") {
		return ""
	}
	return text
}

func ReadTextCandidates(path string, limit int) ([]string, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		return readTextCandidatesFromDir(path, limit)
	}
	if strings.HasSuffix(path, ".jsonl") {
		return readTextCandidatesFromJSONL(path, limit)
	}
	return readTextCandidatesFromFile(path, limit)
}

func readTextCandidatesFromDir(root string, limit int) ([]string, error) {
	var out []string
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() || !isSearchableFile(path) {
			return nil
		}
		items, readErr := ReadTextCandidates(path, remaining(limit, len(out)))
		if readErr != nil {
			return nil
		}
		out = append(out, items...)
		if limit > 0 && len(out) >= limit {
			return filepath.SkipAll
		}
		return nil
	})
	return out, err
}

func readTextCandidatesFromFile(path string, limit int) ([]string, error) {
	if !isSearchableFile(path) {
		return nil, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) > 512*1024 {
		data = data[:512*1024]
	}
	ext := strings.ToLower(filepath.Ext(path))
	if ext == ".json" || ext == ".yaml" || ext == ".yml" {
		var parsed any
		if err := json.Unmarshal(data, &parsed); err == nil {
			return firstClean(extractText(parsed), limit), nil
		}
	}
	return firstClean(strings.Split(string(data), "\n"), limit), nil
}

func isSearchableFile(path string) bool {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".jsonl", ".json", ".md", ".txt", ".yaml", ".yml":
		return true
	default:
		return false
	}
}

func firstClean(items []string, limit int) []string {
	var out []string
	for _, item := range items {
		item = cleanCandidate(item)
		if item == "" {
			continue
		}
		out = append(out, item)
		if limit > 0 && len(out) >= limit {
			break
		}
	}
	return out
}

func remaining(limit, current int) int {
	if limit <= 0 {
		return 0
	}
	left := limit - current
	if left < 0 {
		return 0
	}
	return left
}

package adapters

import (
	"context"
	"errors"
	"os/exec"
	"strings"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/core"
)

type TmuxScanner struct{}

func (s TmuxScanner) Name() string {
	return "tmux"
}

func (s TmuxScanner) Scan(ctx context.Context) core.ScanResult {
	result := core.ScanResult{Source: s.Name()}
	if _, err := exec.LookPath("tmux"); err != nil {
		result.Skipped = true
		result.Message = "tmux not found"
		return result
	}
	format := strings.Join([]string{
		"#{session_name}",
		"#{window_index}",
		"#{pane_index}",
		"#{pane_id}",
		"#{pane_current_path}",
		"#{pane_current_command}",
		"#{pane_title}",
		"#{pane_active}",
	}, "\x1f")
	out, err := exec.CommandContext(ctx, "tmux", "list-panes", "-a", "-F", format).CombinedOutput()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && isNoTmuxServer(string(out)) {
			result.Skipped = true
			result.Message = "tmux server not running"
			return result
		}
		result.Err = err
		return result
	}
	now := time.Now().UTC()
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		parts := strings.Split(line, "\x1f")
		if len(parts) < 8 {
			continue
		}
		sessionName, windowIndex, paneIndex, paneID := parts[0], parts[1], parts[2], parts[3]
		cwd, command, title := parts[4], parts[5], parts[6]
		nativeID := paneID
		sess := core.NewSession("tmux", nativeID)
		sess.ProjectPath = cwd
		sess.Agent = inferAgent(command)
		sess.Title = "tmux " + sessionName + ":" + windowIndex + "." + paneIndex
		if title != "" && title != command {
			sess.Title += " " + core.Truncate(title, 32)
		}
		sess.Status = inferRuntimeStatus(command)
		sess.LastActivityAt = now
		sess.CreatedAt = now
		sess.AttachCommand = core.TmuxAttachCommand(sessionName)
		result.Sessions = append(result.Sessions, sess)
		rt := core.RuntimeInstance{
			ID:            core.RuntimeID("tmux", nativeID),
			SessionID:     sess.ID,
			Backend:       "tmux",
			NativeID:      nativeID,
			Surface:       sessionName + ":" + windowIndex + "." + paneIndex,
			ProjectPath:   cwd,
			Command:       command,
			Status:        sess.Status,
			AttachCommand: sess.AttachCommand,
			UpdatedAt:     now,
		}
		result.Runtimes = append(result.Runtimes, rt)
	}
	return result
}

func inferAgent(command string) string {
	lower := strings.ToLower(command)
	for _, name := range []string{"claude", "copilot", "codex", "hermes", "opencode", "gemini", "cursor-agent", "aider"} {
		if strings.Contains(lower, name) {
			return name
		}
	}
	if command == "" {
		return "terminal"
	}
	return command
}

func isNoTmuxServer(output string) bool {
	output = strings.ToLower(output)
	return strings.Contains(output, "no server running") ||
		strings.Contains(output, "failed to connect to server") ||
		strings.Contains(output, "error connecting to")
}

func inferRuntimeStatus(command string) string {
	switch strings.ToLower(command) {
	case "", "bash", "zsh", "fish", "sh", "tmux":
		return core.StatusIdle
	default:
		return core.StatusUnknown
	}
}

package cli

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/jdbencardinop/tesserasessions/internal/adapters"
	"github.com/jdbencardinop/tesserasessions/internal/config"
	"github.com/jdbencardinop/tesserasessions/internal/core"
	"github.com/jdbencardinop/tesserasessions/internal/store"
	"github.com/jdbencardinop/tesserasessions/internal/summarize"
	"github.com/spf13/cobra"
)

type appContext struct {
	configPath string
	dbPath     string
}

func mergeSessions(primary, secondary []core.Session) []core.Session {
	seen := make(map[string]bool)
	var out []core.Session
	for _, sess := range primary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	for _, sess := range secondary {
		if seen[sess.ID] {
			continue
		}
		seen[sess.ID] = true
		out = append(out, sess)
	}
	return out
}

func Execute() error {
	app := &appContext{}
	root := &cobra.Command{
		Use:   "tss",
		Short: "Inventory local coding-agent sessions",
		Long:  "tss inventories local coding-agent sessions and connects them to Herdr or tmux when available.",
	}
	root.PersistentFlags().StringVar(&app.configPath, "config", "", "config file path")
	root.PersistentFlags().StringVar(&app.dbPath, "db", "", "SQLite database path")
	root.AddCommand(
		app.scanCmd(),
		app.listCmd(),
		app.showCmd(),
		app.doctorCmd(),
		app.summarizeCmd(),
		app.searchCmd(),
		app.titleCmd(),
		app.markCmd(),
		app.pinCmd(),
		app.tagCmd(),
		app.attachCmd(),
		app.openCmd(),
		app.sendCmd(),
	)
	return root.Execute()
}

func (a *appContext) load() (config.Config, error) {
	cfg, err := config.Load(a.configPath)
	if err != nil {
		return cfg, err
	}
	if a.dbPath != "" {
		cfg.Database = a.dbPath
	}
	return cfg, nil
}

func (a *appContext) openStore(cfg config.Config) (*store.Store, error) {
	if err := config.EnsureDirs(cfg); err != nil {
		return nil, err
	}
	return store.Open(cfg.Database)
}

func (a *appContext) scanCmd() *cobra.Command {
	var source string
	var jsonOutput bool
	cmd := &cobra.Command{
		Use:   "scan",
		Short: "Refresh the local session inventory",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := a.load()
			if err != nil {
				return err
			}
			db, err := a.openStore(cfg)
			if err != nil {
				return err
			}
			defer db.Close() //nolint:errcheck
			ctx := cmd.Context()
			type report struct {
				Source   string `json:"source"`
				Sessions int    `json:"sessions"`
				Runtimes int    `json:"runtimes"`
				Skipped  bool   `json:"skipped"`
				Message  string `json:"message,omitempty"`
				Error    string `json:"error,omitempty"`
			}
			var reports []report
			for _, scanner := range adapters.DefaultScanners(cfg) {
				if source != "" && scanner.Name() != source {
					continue
				}
				res := scanner.Scan(ctx)
				r := report{Source: res.Source, Sessions: len(res.Sessions), Runtimes: len(res.Runtimes), Skipped: res.Skipped, Message: res.Message}
				if res.Err != nil {
					r.Error = res.Err.Error()
					_ = db.UpsertSource(ctx, res.Source, "scanner", sourcePath(cfg, res.Source), r.Error)
					reports = append(reports, r)
					continue
				}
				for _, sess := range res.Sessions {
					if err := db.UpsertSession(ctx, sess); err != nil {
						return err
					}
				}
				for _, rt := range res.Runtimes {
					if err := db.UpsertRuntime(ctx, rt); err != nil {
						return err
					}
				}
				_ = db.UpsertSource(ctx, res.Source, "scanner", sourcePath(cfg, res.Source), "")
				reports = append(reports, r)
			}
			if jsonOutput {
				return json.NewEncoder(os.Stdout).Encode(reports)
			}
			for _, r := range reports {
				if r.Error != "" {
					fmt.Printf("%s: error: %s\n", r.Source, r.Error)
					continue
				}
				if r.Skipped {
					fmt.Printf("%s: skipped (%s)\n", r.Source, r.Message)
					continue
				}
				fmt.Printf("%s: %d session(s), %d runtime(s)\n", r.Source, r.Sessions, r.Runtimes)
			}
			count, err := db.CountSessions(ctx)
			if err == nil {
				fmt.Printf("Inventory: %d session(s)\n", count)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&source, "source", "", "scan one source (claude, copilot, herdr, tmux)")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "print JSON")
	return cmd
}

